; flags.asm -- appendix A: every documented instruction, run
; generated by genA.py
        INCLUDE "msx.inc"
        OUTPUT "flags.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM

; Every documented instruction but HALT and RST, run from a table: each
; with the eight Fs of fvals, from every state of its group. A state is
; the registers, popped from it, SP, the word at STK, AF', the byte in the
; PSG's register 0, which port $A2 reads back, and the 8 bytes at WIN.
; measA.py stops at after and reads everything.
WIN     equ $E1FC               ; the bytes read and written: (HL) is WIN+4
STK     equ $E210               ; SP for the runs
TOP     equ $F37E               ; SP between them
S_BC    equ $B1C1               ; BC', DE' and HL' before each run
S_DE    equ $D1E1
S_HL    equ $4161
FVN     equ 8                   ; how many Fs
go      equ VARS                ; JP and the instruction's code
ip      equ VARS + 3            ; the instruction table, where it has got to
gp      equ VARS + 5            ; the group's list of states
gn      equ VARS + 7            ; states left
sv      equ VARS + 8            ; the state
fi      equ VARS + 10           ; which F
spv     equ VARS + 11           ; SP
cur     equ VARS + 16           ; the state, copied: F goes into it
STATE   equ 27                  ; a state's bytes

init:   di
        ld sp,TOP
        VDP_REG 1, $80          ; display off, no signal from the VDP
        call quick              ; page 2: the cartridge's second half
        ld hl,$E000
        ld de,$E001
        ld bc,$03FF
        ld (hl),0
        ldir                    ; the RAM the runs use, cleared
        ld a,$C3
        ld (go),a               ; JP
        ld a,0
        out (PSG_ADDR),a        ; the PSG's register 0, which $A2 reads
        ld hl,itab
        ld (ip),hl
inst:   ld hl,(ip)              ; the next instruction
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,d
        or e
        jp z,done               ; a 0: the table is done
        ld (go+1),de            ; the jump to its code
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (ip),hl
        ex de,hl                ; HL: its group
        ld a,(hl)
        ld (gn),a               ; how many states
        inc hl
        ld (gp),hl
state:  ld hl,(gp)              ; the next state
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (gp),hl
        ld (sv),de
        xor a
        ld (fi),a               ; the first F
run:    ld sp,TOP
        ld a,$3F
        ld i,a                  ; I, the same every run
        im 1
        ld hl,(sv)
        ld de,cur
        ld bc,STATE
        ldir                    ; the state, into the RAM
        ld ix,cur
        ld a,(ix+18)
        out (PSG_WRITE),a       ; what port $A2 reads
        push ix
        pop hl
        ld de,19
        add hl,de
        ld de,WIN
        ld bc,8
        ldir                    ; the bytes at WIN
        ld l,(ix+14)
        ld h,(ix+15)
        ld (STK),hl             ; the word at STK
        ld l,(ix+12)
        ld h,(ix+13)
        ld (spv),hl             ; SP
        exx
        ld bc,S_BC
        ld de,S_DE
        ld hl,S_HL
        exx
        ld l,(ix+16)
        ld h,(ix+17)
        push hl
        pop af
        ex af,af'               ; AF'
        ld a,(fi)
        ld e,a
        ld d,0
        ld hl,fvals
        add hl,de
        ld a,(hl)
        ld (ix+0),a             ; F, into the state
        ld sp,ix
        pop af                  ; and the registers
        pop bc
        pop de
        pop hl
        pop ix
        pop iy
        ld sp,(spv)
        jp go                   ; the instruction's code: back at after
after:  di
        ld sp,TOP
        ld a,(fi)
        inc a
        ld (fi),a
        cp FVN
        jp nz,run               ; the next F
        ld a,(gn)
        dec a
        ld (gn),a
        jp nz,state
        jp inst
done:   jr done

; quick: page 2 shows page 1's primary slot: port $A8 alone. Uses A, B, C
quick:  in a, (PPI_A)           ; 12
        ld b, a                 ;  5
        and %00001100           ;  8  page 1's primary slot
        add a, a                ;  5
        add a, a                ;  5  moved to page 2's bits
        ld c, a                 ;  5
        ld a, b                 ;  5
        and %11001111           ;  8
        or c                    ;  5
        out (PPI_A), a          ; 12  page 2 = this cartridge, too
        ret                     ; 11

fvals:  db $00,$FF,$01,$FE,$10,$11,$02,$03 ; the Fs, in turn

